/**
 * Additional cover template ids (second batch of templates).
 * Spread into COVER_TEMPLATE_IDS in `cover-generator/constants.ts`.
 */
export const COVER_EXTRA_TEMPLATE_IDS = [
  'announcement',
  'big-type',
  'checklist',
  'numbered-steps',
  'api-endpoint',
  'code-diff',
  'status-pill',
  'countdown',
  'logo-marquee',
  'stats-grid',
  'metric-delta',
  'donut-chart',
  'progress-bar',
  'quote',
  'blog-post',
  'podcast-episode',
  'event',
  'profile-card',
  'social-post',
] as const

export type CoverExtraTemplateId = (typeof COVER_EXTRA_TEMPLATE_IDS)[number]

export function isCoverExtraTemplateId(value: string): value is CoverExtraTemplateId {
  return (COVER_EXTRA_TEMPLATE_IDS as readonly string[]).includes(value)
}
import { COVER_EXTRA_TEMPLATE_IDS } from '@/lib/cover-generator/extra-templates/ids'

export {
  COVER_THEME_IDS as COVER_THEMES,
  DEFAULT_COVER_THEME_ID,
  isCoverThemeId as isCoverTheme,
} from '@/lib/cover-generator/themes'

export type { CoverThemeId as CoverTheme } from '@/lib/cover-generator/themes'

/**
 * Layout artboard size (16:9). Templates compose in this space, then scale
 * uniformly into the selected export canvas. Matches blog cover aspect ratio
 * (`BLOG_COVER_ASPECT_CLASS` / Google Discover-friendly covers).
 */
export const COVER_WIDTH = 1200
export const COVER_HEIGHT = 675

export const COVER_SIZE_PRESETS = [
  { id: 'blog', label: 'Blog', width: 1920, height: 1080 },
  { id: 'og', label: 'Open Graph', width: 1200, height: 630 },
  { id: 'twitter', label: 'Twitter / X', width: 1600, height: 900 },
  { id: 'square', label: 'Square', width: 1080, height: 1080 },
  { id: 'instagram-portrait', label: 'Instagram 4:5', width: 1080, height: 1350 },
  { id: 'story', label: 'Story', width: 1080, height: 1920 },
  { id: 'twitter-header', label: 'Twitter header', width: 1500, height: 500 },
  { id: 'newsletter', label: 'Newsletter', width: 610, height: 243 },
] as const

export type CoverSizePresetId = (typeof COVER_SIZE_PRESETS)[number]['id']

/** Default export: blog cover at 1920×1080 (16:9, ≥1200px wide for Discover). */
export const DEFAULT_COVER_SIZE_PRESET_ID = 'blog' satisfies CoverSizePresetId

export function getDefaultCoverSize(): { width: number; height: number } {
  const preset = COVER_SIZE_PRESETS.find((item) => item.id === DEFAULT_COVER_SIZE_PRESET_ID)
  return preset
    ? { width: preset.width, height: preset.height }
    : { width: COVER_WIDTH, height: COVER_HEIGHT }
}

export function getCoverSizePresetKey(width: number, height: number): string {
  const match = COVER_SIZE_PRESETS.find(
    (preset) => preset.width === width && preset.height === height,
  )
  return match?.id ?? `${width}x${height}`
}

export function resolveCoverSizePresetKey(key: string): { width: number; height: number } {
  const preset = COVER_SIZE_PRESETS.find((item) => item.id === key)
  if (preset) return { width: preset.width, height: preset.height }

  const [widthRaw, heightRaw] = key.split('x')
  const width = Number(widthRaw)
  const height = Number(heightRaw)
  if (
    Number.isFinite(width) &&
    Number.isFinite(height) &&
    width >= 320 &&
    width <= 4096 &&
    height >= 200 &&
    height <= 4096
  ) {
    return { width: Math.round(width), height: Math.round(height) }
  }

  return getDefaultCoverSize()
}

export const COVER_TEMPLATE_IDS = [
  'simple-title',
  'integration',
  'integration-icon',
  'showcase-icon',
  'title-icon',
  'screenshot',
  'screenshot-two-line',
  'screenshot-side',
  'screenshot-angled',
  'cards-angled',
  'table',
  'bar-chart',
  'line-chart',
  'cli-code',
  'code-snippet',
  'milestone-split',
  'milestone-centered',
  'version-number',
  'version-title',
  ...COVER_EXTRA_TEMPLATE_IDS,
] as const

export type CoverTemplateId = (typeof COVER_TEMPLATE_IDS)[number]

export const COVER_IMAGE_FORMATS = ['png', 'jpeg', 'avif'] as const
export type CoverImageFormat = (typeof COVER_IMAGE_FORMATS)[number]

export function isCoverTemplateId(value: string): value is CoverTemplateId {
  return (COVER_TEMPLATE_IDS as readonly string[]).includes(value)
}
import { COVER_WIDTH } from '@/lib/cover-generator/constants'

/** Default 3D card transform for perspective product mockups. */
export const PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM = {
  perspective: 1400,
  rotateX: 58,
  rotateZ: -36,
  rotateY: 0,
  translateX: 0,
  translateY: -40,
} as const

export const COVER_SCREENSHOT_ANGLED_CARD_TRANSFORM = {
  rotateX: 51,
  rotateZ: -19,
  rotateY: -2,
  translateX: 225,
  translateY: -25,
} as const

export const PERSPECTIVE_SCREENSHOT_CARD_ASPECT_RATIO = 16 / 9

export const COVER_SCREENSHOT_ANGLED_DEFAULTS = {
  frameWidthPercent: 92,
  /** Scales from the bottom-right corner to fill the right edge and bottom strip. */
  displayScale: 1.65,
} as const

export const PERSPECTIVE_SCREENSHOT_CARD_SURFACE = {
  borderRadius: 24,
  background: '#17171c',
  border: '1px solid rgba(255, 255, 255, 0.08)',
  boxShadow: '0 40px 100px rgba(0, 0, 0, 0.55)',
} as const

export function buildPerspectiveScreenshotCardTransform(options?: {
  rotateX?: number
  rotateY?: number
  rotateZ?: number
  translateX?: number
  translateY?: number
}): string {
  const rotateX = options?.rotateX ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.rotateX
  const rotateY = options?.rotateY ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.rotateY
  const rotateZ = options?.rotateZ ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.rotateZ
  const translateX =
    options?.translateX ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.translateX
  const translateY =
    options?.translateY ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.translateY

  const rotateYPart = rotateY !== 0 ? ` rotateY(${rotateY}deg)` : ''
  const translateXPart = translateX !== 0 ? ` translateX(${translateX}px)` : ''
  const translateYPart = translateY !== 0 ? ` translateY(${translateY}px)` : ''

  return `rotateX(${rotateX}deg) rotateZ(${rotateZ}deg)${rotateYPart}${translateXPart}${translateYPart}`
}

/**
 * Flat 2D transform for @vercel/og/Satori (translate, rotate, skew, scale only).
 * Approximates the DOM 3D card tilt for export.
 */
export function buildPerspectiveScreenshotCardOgTransform(options?: {
  rotateX?: number
  rotateY?: number
  rotateZ?: number
  translateX?: number
  translateY?: number
}): string {
  const rotateX = options?.rotateX ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.rotateX
  const rotateY = options?.rotateY ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.rotateY
  const rotateZ = options?.rotateZ ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.rotateZ
  const translateX =
    options?.translateX ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.translateX
  const translateY =
    options?.translateY ?? PERSPECTIVE_SCREENSHOT_CARD_TRANSFORM.translateY

  const rx = (rotateX * Math.PI) / 180
  const scaleY = Math.cos(rx)
  const skewX = -rotateX * 0.38 + rotateY * 0.5

  const parts: string[] = []
  if (translateX !== 0 || translateY !== 0) {
    parts.push(`translate(${translateX}px, ${translateY}px)`)
  }
  if (rotateZ !== 0) {
    parts.push(`rotate(${rotateZ}deg)`)
  }
  if (Math.abs(skewX) > 0.01) {
    parts.push(`skewX(${skewX.toFixed(2)}deg)`)
  }
  if (Math.abs(scaleY - 1) > 0.001) {
    parts.push(`scaleY(${scaleY.toFixed(4)})`)
  }

  return parts.join(' ')
}

export function computePerspectiveScreenshotCardHeight(cardWidth: number): number {
  return Math.round(cardWidth / PERSPECTIVE_SCREENSHOT_CARD_ASPECT_RATIO)
}

/** Push past the bottom-right anchor so the card sits in the corner. */
export const COVER_SCREENSHOT_ANGLED_LAYOUT = {
  offsetXRatio: -0.13,
  offsetYRatio: -0.06,
} as const

export const COVER_SCREENSHOT_ANGLED_3D_DEFAULTS = {
  rotateX: COVER_SCREENSHOT_ANGLED_CARD_TRANSFORM.rotateX,
  rotateZ: COVER_SCREENSHOT_ANGLED_CARD_TRANSFORM.rotateZ,
  rotateY: COVER_SCREENSHOT_ANGLED_CARD_TRANSFORM.rotateY,
  translateX: COVER_SCREENSHOT_ANGLED_CARD_TRANSFORM.translateX,
  translateY: COVER_SCREENSHOT_ANGLED_CARD_TRANSFORM.translateY,
  displayScale: COVER_SCREENSHOT_ANGLED_DEFAULTS.displayScale,
  posXRatio: COVER_SCREENSHOT_ANGLED_LAYOUT.offsetXRatio,
  posYRatio: COVER_SCREENSHOT_ANGLED_LAYOUT.offsetYRatio,
} as const

export const COVER_SCREENSHOT_ANGLED_3D_LIMITS = {
  rotateX: { min: 15, max: 85, step: 1 },
  rotateZ: { min: -70, max: 10, step: 1 },
  rotateY: { min: -45, max: 45, step: 1 },
  translateX: { min: -300, max: 600, step: 5 },
  translateY: { min: -200, max: 400, step: 5 },
  displayScale: { min: 0.5, max: 4, step: 0.05 },
  posXRatio: { min: -0.6, max: 0.6, step: 0.01 },
  posYRatio: { min: -0.35, max: 0.75, step: 0.01 },
} as const

export function getCoverScreenshotAngledCardTransform(fields: {
  rotateX: number
  rotateY: number
  rotateZ: number
  translateX: number
  translateY: number
}) {
  return {
    rotateX: fields.rotateX,
    rotateY: fields.rotateY,
    rotateZ: fields.rotateZ,
    translateX: fields.translateX,
    translateY: fields.translateY,
  }
}

/** Scale factor from cover reference width (1200) to the active canvas width. */
export function getCoverScreenshotAngledCanvasScale(canvasWidth: number): number {
  return canvasWidth / COVER_WIDTH
}

/** Pixel offsets and perspective scale with canvas size; angles stay in degrees. */
export function scaleCoverScreenshotAngledCardTransform(
  transform: ReturnType<typeof getCoverScreenshotAngledCardTransform>,
  canvasScale: number,
) {
  if (canvasScale === 1) return transform

  return {
    ...transform,
    translateX: transform.translateX * canvasScale,
    translateY: transform.translateY * canvasScale,
  }
}

export function scaleCoverScreenshotAngledPerspective(
  perspective: number,
  canvasScale: number,
): number {
  return perspective * canvasScale
}

/** @deprecated Use computeCoverScreenshotAngledLayoutOffset */
export const PERSPECTIVE_SCREENSHOT_CARD_CLIP_LAYOUT = COVER_SCREENSHOT_ANGLED_LAYOUT

export function computeCoverScreenshotAngledLayoutOffset(
  containerWidth: number,
  containerHeight: number,
  position?: { posXRatio?: number; posYRatio?: number },
): { x: number; y: number } {
  const posXRatio = position?.posXRatio ?? COVER_SCREENSHOT_ANGLED_LAYOUT.offsetXRatio
  const posYRatio = position?.posYRatio ?? COVER_SCREENSHOT_ANGLED_LAYOUT.offsetYRatio

  return {
    x: Math.round(containerWidth * posXRatio),
    y: Math.round(containerHeight * posYRatio),
  }
}

/** Absolute layout for OG/Satori (no calc() or % in transforms). */
export function computeCoverScreenshotAngledOgLayout(options: {
  containerWidth: number
  containerHeight: number
  displayScale?: number
  posXRatio?: number
  posYRatio?: number
}) {
  const displayScale = options.displayScale ?? COVER_SCREENSHOT_ANGLED_DEFAULTS.displayScale
  const offset = computeCoverScreenshotAngledLayoutOffset(
    options.containerWidth,
    options.containerHeight,
    {
      posXRatio: options.posXRatio,
      posYRatio: options.posYRatio,
    },
  )

  return {
    bottom: 0,
    right: 0,
    transform: `translate(${offset.x}px, ${offset.y}px) scale(${displayScale})`,
    transformOrigin: '100% 100%',
  }
}

/** Absolute frame box for OG/Satori (explicit left/top; avoids right/bottom/percent sizing). */
export function computeCoverScreenshotAngledOgFrameBox(options: {
  containerWidth: number
  containerHeight: number
  frameWidth: number
  frameHeight: number
  displayScale?: number
  posXRatio?: number
  posYRatio?: number
}) {
  const displayScale = options.displayScale ?? COVER_SCREENSHOT_ANGLED_DEFAULTS.displayScale
  const offset = computeCoverScreenshotAngledLayoutOffset(
    options.containerWidth,
    options.containerHeight,
    {
      posXRatio: options.posXRatio,
      posYRatio: options.posYRatio,
    },
  )

  const originX = options.frameWidth * 0.2
  const originY = options.frameHeight * 0.2
  const anchorLeft = options.containerWidth - options.frameWidth
  const anchorTop = options.containerHeight - options.frameHeight

  return {
    left: Math.round(anchorLeft - originX * (displayScale - 1) + offset.x),
    top: Math.round(anchorTop - originY * (displayScale - 1) + offset.y),
    width: options.frameWidth,
    height: options.frameHeight,
    scale: displayScale,
    transformOrigin: '20% 20%',
  }
}

/** @deprecated Use computeCoverScreenshotAngledLayoutOffset */
export function computePerspectiveScreenshotCardClipOffset(
  containerWidth: number,
  containerHeight: number,
): { x: number; y: number } {
  return computeCoverScreenshotAngledLayoutOffset(containerWidth, containerHeight)
}
import {
  COVER_SCREENSHOT_ANGLED_3D_DEFAULTS,
  COVER_SCREENSHOT_ANGLED_3D_LIMITS,
  COVER_SCREENSHOT_ANGLED_LAYOUT,
} from '@/lib/perspective-screenshot-card/constants'
import type { CoverRenderData, CoverCardsAngledIconVisibility } from '@/lib/cover-generator/types'

export type { CoverCardsAngledIconVisibility } from '@/lib/cover-generator/types'

export const COVER_CARDS_ANGLED_ICON_VISIBILITY_OPTIONS = [
  { value: 'visible', label: 'Visible' },
  { value: 'fade', label: 'Faded' },
  { value: 'hidden', label: 'Hidden' },
] as const

export const COVER_CARDS_ANGLED_FADED_ICON_OPACITY = 0.35

export const COVER_CARDS_ANGLED_HALO_EMPTY_OPACITY = 0.6

export const COVER_CARDS_ANGLED_ICON_SLOTS = 12

export const COVER_CARDS_ANGLED_HALO_GRID_COLUMNS = 6

export const COVER_CARDS_ANGLED_HALO_BOTTOM_ROWS = 2

export type CoverCardsAngledGridCell =
  | { kind: 'empty' }
  | { kind: 'filled'; iconIndex: number }

export type CoverCardsAngledHaloGrid = {
  columns: number
  rows: number
  cells: CoverCardsAngledGridCell[]
}

/**
 * Frame the filled icon block with empty cards on top, left, right, and bottom.
 * Default 4×3 selection sits in a 6-wide grid with two full-width bottom rows.
 */
export function buildCoverCardsAngledHaloGrid(
  filledColumns: number,
  filledRows: number,
): CoverCardsAngledHaloGrid {
  const gridColumns = Math.max(
    COVER_CARDS_ANGLED_HALO_GRID_COLUMNS,
    filledColumns + 2,
  )
  const gridRows = 1 + filledRows + COVER_CARDS_ANGLED_HALO_BOTTOM_ROWS
  const filledColStart = Math.floor((gridColumns - filledColumns) / 2)
  const filledRowStart = 1

  const cells: CoverCardsAngledGridCell[] = []

  for (let row = 0; row < gridRows; row += 1) {
    for (let col = 0; col < gridColumns; col += 1) {
      const inFilledRow =
        row >= filledRowStart && row < filledRowStart + filledRows
      const inFilledCol =
        col >= filledColStart && col < filledColStart + filledColumns

      if (inFilledRow && inFilledCol) {
        const iconIndex =
          (row - filledRowStart) * filledColumns + (col - filledColStart)
        cells.push({ kind: 'filled', iconIndex })
        continue
      }

      cells.push({ kind: 'empty' })
    }
  }

  return { columns: gridColumns, rows: gridRows, cells }
}

export const COVER_CARDS_ANGLED_DEFAULT_ICONS = [
  '/icons/appwrite.svg',
  '/icons/github.svg',
  '/icons/vercel.svg',
  '/icons/react.svg',
  '/icons/nextjs.svg',
  '/icons/supabase.svg',
  '/icons/stripe.svg',
  '/icons/docker.svg',
  '/icons/node.svg',
  '/icons/python.svg',
  '/icons/flutter.svg',
  '/icons/figma.svg',
] as const

export const COVER_CARDS_ANGLED_GRID = {
  columns: { min: 2, max: 6, default: 4 },
  rows: { min: 2, max: 4, default: 3 },
  iconSize: { min: 48, max: 140, default: 84, step: 4 },
  gap: { min: 8, max: 48, default: 20, step: 2 },
} as const

export const COVER_CARDS_ANGLED_3D_DEFAULTS = {
  ...COVER_SCREENSHOT_ANGLED_3D_DEFAULTS,
  displayScale: 1.9,
  translateX: -65,
  translateY: -90,
  posXRatio: COVER_SCREENSHOT_ANGLED_LAYOUT.offsetXRatio,
  posYRatio: COVER_SCREENSHOT_ANGLED_LAYOUT.offsetYRatio,
} as const

export { COVER_SCREENSHOT_ANGLED_3D_LIMITS as COVER_CARDS_ANGLED_3D_LIMITS }

export const COVER_CARDS_ANGLED_ICON_KEYS = [
  'icon1',
  'icon2',
  'icon3',
  'icon4',
  'icon5',
  'icon6',
  'icon7',
  'icon8',
  'icon9',
  'icon10',
  'icon11',
  'icon12',
] as const

export type CoverCardsAngledIconKey = (typeof COVER_CARDS_ANGLED_ICON_KEYS)[number]

export type CoverCardsAngledIconVisibilityKey = `${CoverCardsAngledIconKey}Visibility`

export function getCoverCardsAngledIconVisibilityKey(
  iconKey: CoverCardsAngledIconKey,
): CoverCardsAngledIconVisibilityKey {
  return `${iconKey}Visibility`
}

export function getCoverCardsAngledIconVisibilityKeys(): CoverCardsAngledIconVisibilityKey[] {
  return getCoverCardsAngledIconKeys().map(getCoverCardsAngledIconVisibilityKey)
}

export function parseCoverCardsAngledIconVisibility(
  value: unknown,
): CoverCardsAngledIconVisibility {
  if (value === 'hidden' || value === 'fade') return value
  return 'visible'
}

export type CoverCardsAngledIconSlot = {
  src: string
  visibility: CoverCardsAngledIconVisibility
}

export function getCoverCardsAngledIconKeys(): CoverCardsAngledIconKey[] {
  return [...COVER_CARDS_ANGLED_ICON_KEYS]
}

export function buildCoverCardsAngledDefaultIconParams(): Record<
  CoverCardsAngledIconKey,
  string
> {
  return Object.fromEntries(
    getCoverCardsAngledIconKeys().map((key, index) => [
      key,
      COVER_CARDS_ANGLED_DEFAULT_ICONS[index] ?? '/icons/appwrite.svg',
    ]),
  ) as Record<CoverCardsAngledIconKey, string>
}

export function getCoverCardsAngledLayoutResetFields() {
  return {
    columns: COVER_CARDS_ANGLED_GRID.columns.default,
    rows: COVER_CARDS_ANGLED_GRID.rows.default,
    iconSize: COVER_CARDS_ANGLED_GRID.iconSize.default,
    gap: COVER_CARDS_ANGLED_GRID.gap.default,
    ...COVER_CARDS_ANGLED_3D_DEFAULTS,
  }
}

export function normalizeCoverCardsAngledData(
  data: CoverRenderData,
): Extract<CoverRenderData, { template: 'cards-angled' }> {
  const cardsData = data.template === 'cards-angled' ? data : null
  const defaultIcons = buildCoverCardsAngledDefaultIconParams()
  const iconFields = Object.fromEntries(
    getCoverCardsAngledIconKeys().map((key) => [
      key,
      cardsData?.[key]?.trim() || defaultIcons[key],
    ]),
  ) as Record<CoverCardsAngledIconKey, string>

  const iconVisibilityFields = Object.fromEntries(
    getCoverCardsAngledIconKeys().map((key) => {
      const visibilityKey = getCoverCardsAngledIconVisibilityKey(key)
      return [
        visibilityKey,
        parseCoverCardsAngledIconVisibility(cardsData?.[visibilityKey]),
      ]
    }),
  ) as Record<CoverCardsAngledIconVisibilityKey, CoverCardsAngledIconVisibility>

  return {
    theme: data.theme,
    format: data.format,
    width: data.width,
    height: data.height,
    template: 'cards-angled',
    columns:
      cardsData && Number.isFinite(cardsData.columns)
        ? cardsData.columns
        : COVER_CARDS_ANGLED_GRID.columns.default,
    rows:
      cardsData && Number.isFinite(cardsData.rows)
        ? cardsData.rows
        : COVER_CARDS_ANGLED_GRID.rows.default,
    iconSize:
      cardsData && Number.isFinite(cardsData.iconSize)
        ? cardsData.iconSize
        : COVER_CARDS_ANGLED_GRID.iconSize.default,
    gap:
      cardsData && Number.isFinite(cardsData.gap)
        ? cardsData.gap
        : COVER_CARDS_ANGLED_GRID.gap.default,
    rotateX:
      cardsData && Number.isFinite(cardsData.rotateX)
        ? cardsData.rotateX
        : COVER_CARDS_ANGLED_3D_DEFAULTS.rotateX,
    rotateZ:
      cardsData && Number.isFinite(cardsData.rotateZ)
        ? cardsData.rotateZ
        : COVER_CARDS_ANGLED_3D_DEFAULTS.rotateZ,
    rotateY:
      cardsData && Number.isFinite(cardsData.rotateY)
        ? cardsData.rotateY
        : COVER_CARDS_ANGLED_3D_DEFAULTS.rotateY,
    translateX:
      cardsData && Number.isFinite(cardsData.translateX)
        ? cardsData.translateX
        : COVER_CARDS_ANGLED_3D_DEFAULTS.translateX,
    translateY:
      cardsData && Number.isFinite(cardsData.translateY)
        ? cardsData.translateY
        : COVER_CARDS_ANGLED_3D_DEFAULTS.translateY,
    displayScale:
      cardsData && Number.isFinite(cardsData.displayScale)
        ? cardsData.displayScale
        : COVER_CARDS_ANGLED_3D_DEFAULTS.displayScale,
    posXRatio:
      cardsData && Number.isFinite(cardsData.posXRatio)
        ? cardsData.posXRatio
        : COVER_CARDS_ANGLED_3D_DEFAULTS.posXRatio,
    posYRatio:
      cardsData && Number.isFinite(cardsData.posYRatio)
        ? cardsData.posYRatio
        : COVER_CARDS_ANGLED_3D_DEFAULTS.posYRatio,
    ...iconFields,
    ...iconVisibilityFields,
  }
}

export function getCoverCardsAngledIconSlots(
  data: Extract<CoverRenderData, { template: 'cards-angled' }>,
): CoverCardsAngledIconSlot[] {
  const normalized = normalizeCoverCardsAngledData(data)
  const slotCount = Math.min(
    normalized.columns * normalized.rows,
    COVER_CARDS_ANGLED_ICON_SLOTS,
  )

  return getCoverCardsAngledIconKeys()
    .slice(0, slotCount)
    .map((key, index) => {
      const visibilityKey = getCoverCardsAngledIconVisibilityKey(key)
      const value = normalized[key]?.trim()
      return {
        src: value || COVER_CARDS_ANGLED_DEFAULT_ICONS[index] || '/icons/appwrite.svg',
        visibility: normalized[visibilityKey] ?? 'visible',
      }
    })
}

export function getCoverCardsAngledIcons(
  data: Extract<CoverRenderData, { template: 'cards-angled' }>,
): string[] {
  const normalized = normalizeCoverCardsAngledData(data)
  const slotCount = Math.min(
    normalized.columns * normalized.rows,
    COVER_CARDS_ANGLED_ICON_SLOTS,
  )

  return getCoverCardsAngledIconKeys()
    .slice(0, slotCount)
    .map((key, index) => {
      const value = normalized[key]?.trim()
      return value || COVER_CARDS_ANGLED_DEFAULT_ICONS[index] || '/icons/appwrite.svg'
    })
}

export function getCoverCardsAngledIconCardMetrics(iconSize: number) {
  const padding = Math.max(10, Math.round(iconSize * (28 / 120)))
  const cardSize = padding * 2 + iconSize
  const radius = Math.max(14, Math.round(iconSize * (32 / 120)))

  return { padding, cardSize, radius }
}

export function isCoverDomPreviewTemplate(template: string): boolean {
  return template === 'screenshot-angled' || template === 'cards-angled'
}
import type { CoverRenderData } from '@/lib/cover-generator/types'

export const COVER_TABLE_GRID = {
  columns: { min: 2, max: 5, default: 4 },
  rows: { min: 1, max: 6, default: 4 },
} as const

