export function clampCoverCodeSnippetFontSize(value: number): number {
  const snapped = Math.round(value)
  return Math.min(
    COVER_CODE_SNIPPET_FONT_SIZE.max,
    Math.max(COVER_CODE_SNIPPET_FONT_SIZE.min, snapped),
  )
}

export function getCoverCodeSnippetLineHeight(codeFontSize: number): number {
  return codeFontSize * COVER_CODE_SNIPPET.codeLineHeightRatio
}

export function getCoverCodeSnippetMaxCharsForLine(
  line: string,
  codeColumnWidthPx: number,
  codeFontSize: number,
): number {
  const charWidth = codeFontSize * COVER_CODE_SNIPPET.monoCharWidthRatio
  if (charWidth <= 0) return 1

  const textAreaWidth =
    codeColumnWidthPx - COVER_CODE_SNIPPET.codePaddingX * 2
  const indentPx = getCoverCodeLineIndentPx(line, codeFontSize, {
    tabWidthSpaces: COVER_CODE_SNIPPET.tabWidthSpaces,
    charWidthRatio: COVER_CODE_SNIPPET.monoCharWidthRatio,
  })

  return Math.max(1, Math.floor((textAreaWidth - indentPx) / charWidth))
}

export function getCoverCodeSnippetMaxLines(
  canvasHeight: number,
  hasTitle = true,
  codeFontSize = COVER_CODE_SNIPPET_FONT_SIZE.default,
): number {
  const titleHeight = hasTitle ? COVER_CODE_SNIPPET.titleLineHeight : 0
  const titleCardGap = hasTitle ? COVER_CODE_SNIPPET.titleCardGap : 0
  const fixedCardHeight =
    COVER_CODE_SNIPPET.headerHeight +
    COVER_CODE_SNIPPET.shellPaddingBottom +
    COVER_CODE_SNIPPET.codePaddingY * 2
  const available =
    canvasHeight -
    titleHeight -
    titleCardGap -
    fixedCardHeight -
    COVER_CODE_SNIPPET.compositionVerticalMargin

  const codeLineHeight = getCoverCodeSnippetLineHeight(codeFontSize)

  return Math.max(1, Math.floor(available / codeLineHeight))
}

export function parseCoverCodeSnippetLines(
  code: string | undefined,
  maxLines = COVER_CODE_SNIPPET.maxLines,
  maxCharsPerLine: number | ((line: string) => number) = 120,
): string[] {
  const rawLines = (code ?? '')
    .split(/\r?\n/)
    .map((line) => line.trimEnd())
    .filter((line, index, lines) => {
      if (line.length > 0) return true
      return lines.slice(index + 1).some((next) => next.length > 0)
    })

  return rawLines.slice(0, maxLines).map((line) => {
    const limit =
      typeof maxCharsPerLine === 'function' ? maxCharsPerLine(line) : maxCharsPerLine
    if (line.length <= limit) return line
    return `${line.slice(0, limit - 1)}…`
  })
}

export function normalizeCoverCodeSnippetData(
  data: CoverRenderData,
): Extract<CoverRenderData, { template: 'code-snippet' }> {
  const snippetData = data.template === 'code-snippet' ? data : null

  return {
    template: 'code-snippet',
    theme: data.theme,
    format: data.format,
    width: data.width,
    height: data.height,
    title: snippetData?.title?.trim() || DEFAULT_CODE_SNIPPET_TITLE,
    code: snippetData?.code?.trim() ? snippetData.code : DEFAULT_CODE_SNIPPET,
    language: parseCoverCodeSnippetLanguage(snippetData?.language),
    codeFontSize: clampCoverCodeSnippetFontSize(
      snippetData && Number.isFinite(snippetData.codeFontSize)
        ? snippetData.codeFontSize
        : COVER_CODE_SNIPPET_FONT_SIZE.default,
    ),
    frameWidthPercent: clampCoverFrameWidthPercent(
      snippetData && Number.isFinite(snippetData.frameWidthPercent)
        ? snippetData.frameWidthPercent
        : COVER_CODE_SNIPPET_DEFAULT_FRAME_WIDTH_PERCENT,
      COVER_SCREENSHOT_FRAME_WIDTH,
    ),
  }
}
/** Tracking for small uppercase cover eyebrows (`cover-eyebrow`). */
export const COVER_EYEBROW_LETTER_SPACING = '0.1em'

/** Strip trailing brand underscores - templates append `_` in brand pink. */
export function stripCoverTitleSuffix(value: string): string {
  return value.trimEnd().replace(/_+$/u, '')
}

/** Marketing eyebrows are uppercase with modest tracking. */
export function formatCoverEyebrow(value: string | undefined): string | undefined {
  const raw = value?.trim()
  if (!raw) return undefined
  return stripCoverTitleSuffix(raw).toUpperCase() || undefined
}

export function escapeXml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;')
}

function withLineEllipsis(line: string, maxCharsPerLine: number): string {
  const withoutTrail = line.replace(/[.\s]+$/u, '').trimEnd()
  const budget = Math.max(0, maxCharsPerLine - 3)
  if (withoutTrail.length > budget) {
    return `${withoutTrail.slice(0, budget).trimEnd()}...`
  }
  return `${withoutTrail}...`
}

function splitWordToFit(word: string, maxCharsPerLine: number): string[] {
  if (word.length <= maxCharsPerLine) return [word]

  const parts: string[] = []
  for (let index = 0; index < word.length; index += maxCharsPerLine) {
    parts.push(word.slice(index, index + maxCharsPerLine))
  }
  return parts
}

export function wrapTextLines(
  text: string,
  maxCharsPerLine: number,
  maxLines: number,
): string[] {
  if (maxLines <= 0) return []

  const words = text
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .flatMap((word) => splitWordToFit(word, maxCharsPerLine))
  if (!words.length) return []

  const lines: string[] = []
  let current = words[0] ?? ''

  for (const word of words.slice(1)) {
    const next = `${current} ${word}`
    if (next.length <= maxCharsPerLine) {
      current = next
      continue
    }
    lines.push(current)
    current = word
    if (lines.length >= maxLines) break
  }

  if (lines.length < maxLines) {
    lines.push(current)
  }

  const wrapped = lines.slice(0, maxLines)
  const joinedLines = wrapped.join(' ')
  const sourceText = words.join(' ')
  if (sourceText.length > joinedLines.length) {
    wrapped[maxLines - 1] = withLineEllipsis(wrapped[maxLines - 1] ?? '', maxCharsPerLine)
  }

  return wrapped
}

/**
 * Like {@link wrapTextLines}, but explicit line breaks (`\n`) in `text` start a
 * new line. Each segment still wraps at `maxCharsPerLine`; the total never
 * exceeds `maxLines` and the last line is ellipsized when text is cut.
 */
export function wrapTextLinesWithBreaks(
  text: string,
  maxCharsPerLine: number,
  maxLines: number,
): string[] {
  if (maxLines <= 0) return []

  const segments = text
    .split(/\r?\n/u)
    .map((segment) => segment.trim())
    .filter(Boolean)
  if (segments.length <= 1) {
    return wrapTextLines(segments[0] ?? '', maxCharsPerLine, maxLines)
  }

  // `wrapTextLines` ellipsizes a segment it has to cut, so only whole segments
  // that never fit need a trailing marker here.
  const lines: string[] = []
  let droppedSegment = false
  for (const [index, segment] of segments.entries()) {
    const remaining = maxLines - lines.length
    if (remaining <= 0) {
      droppedSegment = true
      break
    }
    const isLastSegment = index === segments.length - 1
    // Leave room for later segments so a long first line does not eat every slot.
    const budget = isLastSegment
      ? remaining
      : Math.max(1, remaining - (segments.length - index - 1))
    lines.push(...wrapTextLines(segment, maxCharsPerLine, budget))
  }

  if (droppedSegment && lines.length) {
    const last = lines[lines.length - 1] ?? ''
    if (!last.endsWith('...')) {
      lines[lines.length - 1] = withLineEllipsis(last, maxCharsPerLine)
    }
  }

  return lines
}

export function clampNumber(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

export function parseBooleanParam(
  value: string | null | undefined,
  fallback: boolean,
): boolean {
  if (value == null || value === '') return fallback
  const normalized = value.trim().toLowerCase()
  if (normalized === '1' || normalized === 'true' || normalized === 'yes') {
    return true
  }
  if (normalized === '0' || normalized === 'false' || normalized === 'no') {
    return false
  }
  return fallback
}

export function parseNumberParam(
  value: string | null | undefined,
  fallback: number,
  min?: number,
  max?: number,
): number {
  if (value == null || value === '') return fallback
  const parsed = Number(value)
  if (!Number.isFinite(parsed)) return fallback
  if (min != null && max != null) return clampNumber(parsed, min, max)
  return parsed
}
